actualRule.text:
def(
    "삼각비",
    "16",
    "삼각비의 표를 이용하여 삼각비의 값 구하기",
    SEC.값,
    "기본",
    (rng) => {
      const b = intBetween(rng, 30, 58);
      const fn = intBetween(rng, 0, 2);
      const table = [0, 1, 2].map((i) => tableValue(fn, b + i));
      const mode = intBetween(rng, 0, 2);
      const rows = [0, 1, 2]
        .map((i) => `$${trigText(fn, b + i)}=${table[i]!.toFixed(4)}$`)
        .join(", ");
      const head = `삼각비의 표에서 ${rows}이다.`;
      if (mode === 0) {
        return {
          // 소수 넷째 자리까지 적으므로 마지막에 읽는 숫자는 만 배 한 정수의 끝 자리다.
          content: `${head} 이때 $${FN_NAMES[fn]} x=${table[2]!.toFixed(4)}$${eulReul(Math.round(table[2]! * 10000))} 만족시키는 $x$의 크기를 구하시오.`,
          answer: `$${b + 2}^\\circ$`,
          solution: `표에서 값이 $${table[2]!.toFixed(4)}$인 각을 찾으면 $${b + 2}^\\circ$이다.\n따라서 $x=${b + 2}^\\circ$이다.`,
          facts: { b, fn, mode, target: b + 2, val: table[2]! },
          figureSpec: null,
        };
      }
      if (mode === 1) {
        const sum = Number((table[0]! + table[2]!).toFixed(4));
        return {
          content: `${head} 이때 $${trigText(fn, b)}+${trigText(fn, b + 2)}$의 값을 구하시오.`,
          answer: `$${sum.toFixed(4)}$`,
          solution: `표에서 $${trigText(fn, b)}=${table[0]!.toFixed(4)}$, $${trigText(fn, b + 2)}=${table[2]!.toFixed(4)}$이다.\n따라서 구하는 값은 $${table[0]!.toFixed(4)}+${table[2]!.toFixed(4)}=${sum.toFixed(4)}$이다.`,
          facts: { b, fn, mode, target: b, val: sum },
          figureSpec: null,
        };
      }
      // 차 — 큰 값에서 작은 값을 뺀다($\cos$ 는 각이 커질수록 작아진다).
      const hi = fn === 1 ? b : b + 2;
      const lo = fn === 1 ? b + 2 : b;
      const diff = Number((tableValue(fn, hi) - tableValue(fn, lo)).toFixed(4));
      return {
        content: `${head} 이때 $${trigText(fn, hi)}-${trigText(fn, lo)}$의 값을 구하시오.`,
        answer: `$${diff.toFixed(4)}$`,
        solution: `표에서 $${trigText(fn, hi)}=${tableValue(fn, hi).toFixed(4)}$, $${trigText(fn, lo)}=${tableValue(fn, lo).toFixed(4)}$이다.\n따라서 구하는 값은 $${tableValue(fn, hi).toFixed(4)}-${tableValue(fn, lo).toFixed(4)}=${diff.toFixed(4)}$이다.`,
        facts: { b, fn, mode, target: hi, val: diff },
        figureSpec: null,
      };
    },
  ),
